        throw new IllegalArgumentException("Input cannot be null");
    }

    StringBuilder result = new StringBuilder();
    boolean escaping = false;
    for (char c : input.toCharArray()) {
        if (c == '\\') {
            escaping = !escaping;
        } else if (escaping) {
            char replacement;
            switch (c) {
                case '"':
                    replacement = '"';
                    break;
                case '#':
                    replacement = '#';
                    break;
                case '|':
                    replacement = '|';
                    break;
                default:
                    throw new IllegalArgumentException("Invalid escape sequence: \\U" + Integer.toHexString(c));
            }
            result.append(replacement);
            escaping = false;
        } else {
            result.append(c);
        }
    }

    return result.toString();
}

