public static String trimTrailingWhitespace(String str) {
    if (str == null) {
        throw new IllegalArgumentException("The string cannot be null.");
    }

    int length = str.length();
    if (length == 0) {
        return str;  // If the string is empty, no trailing whitespace to remove.
    }

    int lastNonWhitespaceIndex = length - 1;
    // Find the last non-whitespace character in the string.
    while ( lastNonWhitespaceIndex >= 0 && Character.isWhitespace(str.charAt(lastNonWhitespaceIndex))) {
        lastNonWhitespaceIndex--;
    }

    // Return the substring from the start to the last non-whitespace character.
    return str.substring(0, lastNonWhitespaceIndex + 1);
}

