        if (b == -1) {
            throw new EOFException("Unexpected end of stream");
        }
        long part = ((b & 0x7f) << (7 * (num - 1)));
        if (num == 9) { // at most 8 bytes
            throw new IOException("Varint is too large to fit into a long");
        }
        value |= part;
        num++;
