public String readString() throws IOException {
    // Step 1: Check if the stream is at the beginning
    if (stream == null || stream.isClosed()) {
        throw new IOException("Stream is not open.");
    }

    // Step 2: Read the string from the stream
    StringBuffer buffer = new StringBuffer();
    int ch;
    while ((ch = stream.read()) != -1 && Character.isLetterOrDigit((char) ch)) {
        buffer.append((char) ch);
    }

    // Step 3: Remove any trailing whitespace
    while (buffer.length() > 0 && Character.isWhitespace(buffer.charAt(buffer.length() - 1))) {
        buffer.deleteCharAt(buffer.length() - 1);
    }

    // Step 4: Return the string
    return buffer.toString();
}

